// synth-worker.ts
//
// Purpose: Web Worker entry point for off-main-thread synthesis
//
// This module:
// - Creates a Synth instance (no AudioBackend — null AudioDriver)
// - Handles messages from the main thread (render, play, pause, setSong, etc.)
// - Posts rendered Float32Array buffers back with transferables

import { Synth } from "./synth";

const synth: Synth = new Synth();

/** Current song serialized — preserved across pause/play so we can re-init after setSong. */
let currentSongData: string = "";

self.onmessage = (e: MessageEvent) => {
	const msg = e.data;
	if (!msg || !msg.type) return;

	switch (msg.type) {
		case "init": {
			// Initialize: set song and sample rate
			if (typeof msg.songData === "string") {
				currentSongData = msg.songData;
				synth.setSong(currentSongData);
			}
			if (typeof msg.sampleRate === "number") {
				(synth as any).samplesPerSecond = msg.sampleRate;
			}
			if (typeof msg.volume === "number") {
				synth.volume = msg.volume;
			}
			synth.warmUpSynthesizer(null);
			postMessage({ type: "init-complete" });
			break;
		}

		case "setSong": {
			if (typeof msg.songData === "string") {
				currentSongData = msg.songData;
				synth.setSong(currentSongData);
			}
			postMessage({ type: "song-set" });
			break;
		}

		case "render": {
			const bufferSize: number = msg.bufferSize ?? 2048;
			const playSong: boolean = msg.playSong ?? false;
			const requestId: number = msg.requestId ?? 0;

			// If the worker is not playing and the fade is already
			// complete (_stopFadeSamplesRemaining = 0), synthesize()
			// returns full-volume audio (no fade ramp). This happens
			// when a render request was dispatched before fade-complete
			// but arrives after — the stale buffer would pop over silence
			// in the drain. Return silence instead.
			if (!synth.playing && (synth as any)._stopFadeSamplesRemaining === 0 && (synth as any).fadingOut === false) {
				postMessage(
					{
						type: "audio",
						requestId,
						left: new Float32Array(bufferSize),
						right: new Float32Array(bufferSize),
						playhead: synth.playhead,
						bar: synth.currentBar,
						isPlayingSong: synth.playing,
						totalSamplesRendered: (synth as any).totalSamplesRendered,
						fadingOut: false,
						recording: false,
						outVolumeCap: 0,
					},
				);
				break;
			}

			const left = new Float32Array(bufferSize);
			const right = new Float32Array(bufferSize);

			synth.synthesize(left, right, bufferSize, playSong);

			postMessage(
				{
					type: "audio",
					requestId,
					left,
					right,
					playhead: synth.playhead,
					bar: synth.currentBar,
					isPlayingSong: synth.playing,
					totalSamplesRendered: (synth as any).totalSamplesRendered,
					fadingOut: synth.fadingOut,
					recording: synth.recording,
					outVolumeCap: (synth as any).song?.outVolumeCap ?? 0,
				},
				[left.buffer, right.buffer] as any,
			);

			// After sending the last fade buffer, signal the main thread
			// that the fade is finished. The main thread waits until the
			// pool and worklet queue are fully drained before deactivating.
			if (!synth.playing && (synth as any)._stopFadeSamplesRemaining === 0 && (synth as any).fadingOut === false) {
				postMessage({ type: "fade-complete" });
			}
			break;
		}

		case "play": {
			// Cancel any pending stop fade and free tones — mirrors the
			// main-thread Synth.play() logic. Without this, residual
			// _stopFadeSamplesRemaining from a previous pause causes
			// gain-reduced buffers followed by a sudden gain jump (click)
			// when the counter hits 0 during playback.
			(synth as any)._stopFadeSamplesRemaining = 0;
			synth.freeAllTones();
			synth.warmUpSynthesizer(null);
			(synth as any).isPlayingSong = true;
			postMessage({ type: "state-change", isPlayingSong: true });
			break;
		}

		case "pause": {
			synth.pause();
			postMessage({
				type: "state-change",
				isPlayingSong: synth.playing,
				bar: synth.currentBar,
				playhead: synth.playhead,
			});
			break;
		}

		case "goToBar": {
			synth.goToBar(msg.bar ?? 0);
			postMessage({ type: "state-change", bar: synth.currentBar, playhead: synth.playhead });
			break;
		}

		case "snapToStart": {
			synth.snapToStart();
			postMessage({ type: "state-change", bar: synth.currentBar, playhead: synth.playhead });
			break;
		}

		case "setVolume": {
			if (msg.volume != null) synth.volume = msg.volume;
			break;
		}

		case "setLoop": {
			if (msg.loopBarStart != null) (synth as any).loopBar = msg.loopBarStart;
			if (msg.loopBarEnd != null)
				(synth as any).loopLength = msg.loopBarEnd - msg.loopBarStart;
			if (msg.loopRepeatCount != null) (synth as any).loopRepeatCount = msg.loopRepeatCount;
			break;
		}

		case "freeAllTones": {
			synth.freeAllTones();
			break;
		}

		case "resetEffects": {
			synth.resetEffects();
			break;
		}

		case "initModFilters": {
			synth.initModFilters(null);
			break;
		}

		case "computeLatestModValues": {
			(synth as any).computeLatestModValues();
			break;
		}

		case "setRenderingSong": {
			(synth as any).renderingSong = msg.rendering ?? false;
			break;
		}

		case "getTotalSamples": {
			const total = synth.getTotalSamples(
				msg.enableIntro ?? false,
				msg.enableOutro ?? false,
				msg.loop ?? 0,
			);
			postMessage({ type: "result", requestId: msg.requestId ?? 0, value: total });
			break;
		}

		case "getSamplesPerBar": {
			const spb = (synth as any).getSamplesPerBar();
			postMessage({ type: "result", requestId: msg.requestId ?? 0, value: spb });
			break;
		}

		case "updateLiveInput": {
			// Live input state is managed through synthesize() playSong flag
			// and maintainLiveInput on main thread. The worker's synthesizer
			// handles live tones when playSong=true and live input pitches exist.
			break;
		}

		default:
			break;
	}
};

// Signal that the worker is ready
postMessage({ type: "worker-ready" });
